use walkdir::WalkDir;

mod ascii;

#[derive(Parser)]
#[command(name = "RnR is a command-line tool to rename multiple files and directories that\nsupports regular expressions", version = "0.5.1")]
struct Cli {
    #[command(subcommand)]
    command: Commands,

    #[command(flatten)]
    global_opts: GlobalOpts,
}

#[derive(Subcommand)]
enum Commands {
    /// Rename files and directories using a regular expression
    Regex {
        /// Expression to match (can be a regex)
        expression: String,

        /// Expression replacement (use single quotes for capture groups)
        replacement: String,

        /// Target paths
        #[arg(required = true)]
        paths: Vec<String>,

        #[command(flatten)]
        opts: CommonOpts,
    },

    /// Read operations from a dump file
    FromFile {
        /// Dump file path
        dumpfile: String,

        #[command(flatten)]
        opts: FromFileOpts,
    },

    /// Replace file name UTF-8 chars with ASCII chars representation
    ToAscii {
        /// Target paths
        #[arg(required = true)]
        paths: Vec<String>,

        #[command(flatten)]
        opts: CommonOpts,
    },
}

#[derive(Parser)]
struct GlobalOpts {
    #[arg(short, long)]
    help: bool,

    #[arg(short = 'V', long)]
    version: bool,
}

#[derive(Parser)]
struct CommonOpts {
    /// Only show what would be done (default mode)
    #[arg(short, long)]
    dry_run: bool,

    /// Make actual changes to files
    #[arg(short, long)]
    force: bool,

    /// Generate file backups before renaming
    #[arg(short, long)]
    backup: bool,

    /// Do not print any information
    #[arg(short, long)]
    silent: bool,

    /// Set color output mode
    #[arg(long, default_value = "auto")]
    color: ColorMode,

    /// Force dumping operations into a file even in dry-run mode
    #[arg(long)]
    dump: bool,

    /// Set the dump file prefix
    #[arg(long, default_value = "rnr-")]
    dump_prefix: String,

    /// Do not dump operations into a file
    #[arg(long)]
    no_dump: bool,

    /// Limit of replacements, all matches if set to 0
    #[arg(short, long)]
    replace_limit: Option<usize>,

    /// Apply a transformation to replacements including captured groups
    #[arg(short, long)]
    replace_transform: Option<ReplaceTransform>,

    /// Rename matching directories
    #[arg(short = 'D', long)]
    include_dirs: bool,

    /// Recursive mode
    #[arg(short, long)]
    recursive: bool,

    /// Set max depth in recursive mode
    #[arg(short, long)]
    max_depth: Option<usize>,

    /// Include hidden files and directories
    #[arg(short, long)]
    hidden: bool,
}

#[derive(Parser)]
struct FromFileOpts {
    /// Only show what would be done (default mode)
    #[arg(short, long)]
    dry_run: bool,

    /// Make actual changes to files
    #[arg(short, long)]
    force: bool,

    /// Generate file backups before renaming
    #[arg(short, long)]
    backup: bool,

    /// Do not print any information
    #[arg(short, long)]
    silent: bool,

    /// Set color output mode
    #[arg(long, default_value = "auto")]
    color: ColorMode,

    /// Force dumping operations into a file even in dry-run mode
    #[arg(long)]
    dump: bool,

    /// Set the dump file prefix
    #[arg(long, default_value = "rnr-")]
    dump_prefix: String,

    /// Do not dump operations into a file
    #[arg(long)]
    no_dump: bool,

    /// Undo the operations from the dump file
    #[arg(short, long)]
    undo: bool,
}

#[derive(Clone, Copy, Debug)]
enum ColorMode {
    Always,
    Never,
    Auto,
}

impl std::str::FromStr for ColorMode {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "always" => Ok(ColorMode::Always),
            "never" => Ok(ColorMode::Never),
            "auto" => Ok(ColorMode::Auto),
            _ => Err(format!("Invalid color mode: {}", s)),
        }
    }
}

#[derive(Clone, Copy, Debug)]
enum ReplaceTransform {
    Upper,
    Lower,
    Ascii,
}

impl std::str::FromStr for ReplaceTransform {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "upper" => Ok(ReplaceTransform::Upper),
            "lower" => Ok(ReplaceTransform::Lower),
            "ascii" => Ok(ReplaceTransform::Ascii),
            _ => Err(format!("Invalid replace transform: {}", s)),
        }
    }
}

#[derive(Serialize, Deserialize, Debug)]
struct DumpFile {
    date: String,
    operations: Vec<Operation>,
}

#[derive(Serialize, Deserialize, Debug, Clone)]
struct Operation {
    source: String,
    target: String,
}

fn should_use_color(mode: ColorMode) -> bool {
    match mode {
        ColorMode::Always => true,
        ColorMode::Never => false,
        ColorMode::Auto => atty::is(atty::Stream::Stdout),
    }
}

fn apply_transform(text: &str, transform: ReplaceTransform) -> String {
    match transform {
        ReplaceTransform::Upper => text.to_uppercase(),
        ReplaceTransform::Lower => text.to_lowercase(),
        ReplaceTransform::Ascii => ascii::to_ascii(text),
    }
}

fn perform_rename(
    source: &Path,
    target: &Path,
    force: bool,
    backup: bool,
    silent: bool,
    use_color: bool,
) -> Result<(), Box<dyn std::error::Error>> {
    if force {
        if backup {
            let backup_path = format!("{}.bk", source.display());
            if !silent {
                println!("Info:  Backup created - {} -> {}", source.display(), backup_path);
            }
            fs::copy(source, &backup_path)?;
        }
        fs::rename(source, target)?;
    }

    if !silent {
        if use_color {
            println!(
                "\x1b[90m{}\x1b[0m -> \x1b[1;31m{}\x1b[0m\x1b[32m{}\x1b[0m\x1b[1;31m{}\x1b[0m\x1b[32m{}\x1b[0m",
                source.display(),
                &target.file_name().unwrap().to_string_lossy()[..1],
                "",
                target.file_name().unwrap().to_string_lossy().chars().skip(1).take(target.file_name().unwrap().to_string_lossy().len() - 1).collect::<String>()[..target.file_name().unwrap().to_string_lossy().len() - 2.max(1)].to_string(),
                target.file_name().unwrap().to_string_lossy().chars().last().map(|c| c.to_string()).unwrap_or_default()
            );
        } else {
            println!("{} -> {}", source.display(), target.display());
        }
    }

    Ok(())
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    if args.len() > 1 && args[1] == "--version" {
        println!("rnr 0.5.1");
        return;
    }

    if args.len() == 1 || (args.len() > 1 && (args[1] == "--help" || args[1] == "-h")) {
        println!("RnR is a command-line tool to rename multiple files and directories that");
        println!("supports regular expressions");
        println!();
        println!("Usage: executable <COMMAND>");
        println!();
        println!("Commands:");
        println!("  regex      Rename files and directories using a regular expression");
        println!("  from-file  Read operations from a dump file");
        println!("  to-ascii   Replace file name UTF-8 chars with ASCII chars representation");
        println!("  help       Print this message or the help of the given subcommand(s)");
        println!();
        println!("Options:");
        println!("  -h, --help     Print help");
        println!("  -V, --version  Print version");
        return;
    }

    let cli = match Cli::try_parse() {
        Ok(cli) => cli,
        Err(e) => {
            eprintln!("{}", e);
            process::exit(2);
        }
    };

    match cli.command {
        Commands::Regex {
            expression,
            replacement,
            paths,
            opts,
        } => {
            handle_regex(&expression, &replacement, &paths, opts);
        }
        Commands::FromFile { dumpfile, opts } => {
            handle_from_file(&dumpfile, opts);
        }
        Commands::ToAscii { paths, opts } => {
            handle_to_ascii(&paths, opts);
        }
    }
}

fn handle_regex(expression: &str, replacement: &str, paths: &[String], opts: CommonOpts) {
    if opts.hidden && !opts.recursive {
        eprintln!("error: the following required arguments were not provided:\n  --recursive");
        eprintln!();
        eprintln!("Usage: executable regex --recursive --hidden <EXPRESSION> <REPLACEMENT> <PATH(S)>...");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        process::exit(2);
    }

    let regex = match Regex::new(expression) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("Error: Invalid regex: {}", e);
            process::exit(1);
        }
    };

    let use_color = should_use_color(opts.color);
    let mut operations = Vec::new();

    if opts.recursive {
        for path_str in paths {
            let path = Path::new(path_str);
            for entry in WalkDir::new(path)
                .into_iter()
                .filter_map(|e| e.ok())
                .filter(|e| {
                    if !opts.hidden && e.file_name().to_string_lossy().starts_with('.') {
                        return false;
                    }
                    if let Some(max_depth) = opts.max_depth {
                        let depth = e.path().components().count().saturating_sub(path.components().count());
                        if depth > max_depth {
                            return false;
                        }
                    }
                    if e.path().is_dir() && !opts.include_dirs {
                        return e.path() == path || e.depth() == 0;
                    }
                    true
                })
            {
                let file_path = entry.path();
                let file_name = file_path.file_name().unwrap().to_string_lossy();

                if regex.is_match(&file_name) {
                    let new_name = apply_replacements(
                        &file_name,
                        &regex,
                        replacement,
                        opts.replace_limit,
                        opts.replace_transform,
                    );

                    if new_name != *file_name {
                        let new_path = file_path.parent().unwrap().join(&*new_name);
                        operations.push((file_path.to_path_buf(), new_path));
                    }
                }
            }
        }
    } else {
        for path_str in paths {
            let path = Path::new(path_str);
            if path.is_file() {
                let file_name = path.file_name().unwrap().to_string_lossy();

                if regex.is_match(&file_name) {
                    let new_name = apply_replacements(
                        &file_name,
                        &regex,
                        replacement,
                        opts.replace_limit,
                        opts.replace_transform,
                    );

                    if new_name != *file_name {
                        let new_path = path.parent().unwrap().join(&*new_name);
                        operations.push((path.to_path_buf(), new_path));
                    }
                }
            }
        }
    }

    if operations.is_empty() {
        return;
    }

    // Check for duplicate names
    let mut name_map: HashMap<String, Vec<String>> = HashMap::new();
    for (old, new) in &operations {
        let new_name = new.to_string_lossy().to_string();
        name_map.entry(new_name).or_insert_with(Vec::new).push(old.to_string_lossy().to_string());
    }

    for (new_name, old_names) in name_map.iter() {
        if old_names.len() > 1 {
            if !opts.silent {
                eprintln!("Error: Files will have the same name");
                eprintln!();
                for old in old_names {
                    eprintln!("{}->", old);
                }
                eprintln!("{}", new_name);
                eprintln!();
                for old in old_names {
                    eprintln!("{}->", old);
                }
                eprintln!("{}", new_name);
                eprintln!();
            }
            process::exit(1);
        }
    }

    if !opts.silent && !opts.force {
        println!("This is a DRY-RUN");
    }

    for (old, new) in &operations {
        if !opts.silent {
            if use_color {
                let old_name = old.file_name().unwrap().to_string_lossy();
                let new_name = new.file_name().unwrap().to_string_lossy();
                print_colored_rename(&old_name, &new_name);
            } else {
                println!("{} -> {}", old.display(), new.display());
            }
        }
    }

    if opts.force {
        for (old, new) in &operations {
            if opts.backup && !opts.silent {
                let backup_path = format!("{}.bk", old.display());
                println!("Info:  Backup created - {} -> {}", old.display(), backup_path);
                let _ = fs::copy(old, &backup_path);
            }
            if let Err(e) = fs::rename(old, new) {
                eprintln!("Error renaming {} to {}: {}", old.display(), new.display(), e);
                process::exit(1);
            }
        }
    }

    // Handle dump file
    if !opts.no_dump && (opts.dump || opts.force) {
        let dump_ops: Vec<Operation> = operations
            .iter()
            .map(|(src, tgt)| Operation {
                source: src.file_name().unwrap().to_string_lossy().to_string(),
                target: tgt.file_name().unwrap().to_string_lossy().to_string(),
            })
            .collect();

        let dump = DumpFile {
            date: Local::now().format("%Y-%m-%d %H:%M:%S").to_string(),
            operations: dump_ops,
        };

        let filename = format!("{}{}.json", opts.dump_prefix, Local::now().format("%Y-%m-%d_%H%M%S"));
        if let Ok(json) = serde_json::to_string_pretty(&dump) {
            let _ = fs::write(&filename, json);
        }
    }
}

fn apply_replacements(
    text: &str,
    regex: &Regex,
    replacement: &str,
    limit: Option<usize>,
    transform: Option<ReplaceTransform>,
) -> String {
    let limit = limit.unwrap_or(0);

    if limit == 0 {
        // Replace all
        let mut result = text.to_string();
        if let Some(t) = transform {
            result = regex.replace_all(&result, |caps: &regex::Captures| {
                let matched = &caps[0];
                apply_transform(matched, t)
            }).to_string();
        } else {
            result = regex.replace_all(&result, replacement).to_string();
        }
        result
    } else {
        // Replace limited
        let mut result = text.to_string();
        let mut count = 0;
        for (i, m) in regex.find_iter(text).enumerate() {
            if i >= limit {
                break;
            }
            let matched = &text[m.start()..m.end()];
            let replacement_text = if let Some(t) = transform {
                apply_transform(matched, t)
            } else {
                replacement.to_string()
            };
            result.replace_range(m.start()..m.end(), &replacement_text);
            count += 1;
        }
        result
    }
}

fn print_colored_rename(old_name: &str, new_name: &str) {
    print!("\x1b[90m{}\x1b[0m -> ", old_name);

    // Simple color logic - highlight differences
    for (old_c, new_c) in old_name.chars().zip(new_name.chars()) {
        if old_c != new_c {
            print!("\x1b[1;31m{}\x1b[0m", new_c);
        } else {
            print!("{}", new_c);
        }
    }

    // Handle extra characters
    if new_name.len() > old_name.len() {
        print!("\x1b[32m{}\x1b[0m", &new_name[old_name.len()..]);
    }

    println!();
}

fn handle_from_file(dumpfile: &str, opts: FromFileOpts) {
    let use_color = should_use_color(opts.color);

    match fs::read_to_string(dumpfile) {
        Ok(content) => {
            match serde_json::from_str::<DumpFile>(&content) {
                Ok(dump) => {
                    let mut ops = dump.operations.clone();

                    if opts.undo {
                        // Reverse the operations
                        for op in &mut ops {
                            std::mem::swap(&mut op.source, &mut op.target);
                        }
                    }

                    if !opts.silent && !opts.force {
                        println!("This is a DRY-RUN");
                    }

                    for op in &ops {
                        if !opts.silent {
                            println!("{} -> {}", op.source, op.target);
                        }
                    }

                    if opts.force {
                        for op in &ops {
                            let src = Path::new(&op.source);
                            let dst = Path::new(&op.target);

                            if opts.backup && !opts.silent {
                                let backup_path = format!("{}.bk", src.display());
                                println!("Info:  Backup created - {} -> {}", src.display(), backup_path);
                                let _ = fs::copy(src, &backup_path);
                            }

                            if let Err(e) = fs::rename(src, dst) {
                                eprintln!("Error renaming {} to {}: {}", src.display(), dst.display(), e);
                                process::exit(1);
                            }
                        }
                    }

                    // Handle dump file
                    if !opts.no_dump && (opts.dump || opts.force) {
                        let dump = DumpFile {
                            date: Local::now().format("%Y-%m-%d %H:%M:%S").to_string(),
                            operations: ops,
                        };

                        let filename = format!("{}{}.json", opts.dump_prefix, Local::now().format("%Y-%m-%d_%H%M%S"));
                        if let Ok(json) = serde_json::to_string_pretty(&dump) {
                            let _ = fs::write(&filename, json);
                        }
                    }
                }
                Err(e) => {
                    eprintln!("Error parsing dump file: {}", e);
                    process::exit(1);
                }
            }
        }
        Err(e) => {
            eprintln!("Error reading dump file: {}", e);
            process::exit(1);
        }
    }
}

fn handle_to_ascii(paths: &[String], opts: CommonOpts) {
    let use_color = should_use_color(opts.color);
    let mut operations = Vec::new();

    if opts.recursive {
        for path_str in paths {
            let path = Path::new(path_str);
            for entry in WalkDir::new(path)
                .into_iter()
                .filter_map(|e| e.ok())
                .filter(|e| {
                    if !opts.hidden && e.file_name().to_string_lossy().starts_with('.') {
                        return false;
                    }
                    if let Some(max_depth) = opts.max_depth {
                        let depth = e.path().components().count().saturating_sub(path.components().count());
                        if depth > max_depth {
                            return false;
                        }
                    }
                    if e.path().is_dir() && !opts.include_dirs {
                        return false;
                    }
                    true
                })
            {
                let file_path = entry.path();
                let file_name = file_path.file_name().unwrap().to_string_lossy();
                let new_name = ascii::to_ascii(&file_name);

                if new_name != *file_name {
                    let new_path = file_path.parent().unwrap().join(&new_name);
                    operations.push((file_path.to_path_buf(), new_path));
                }
            }
        }
    } else {
        for path_str in paths {
            let path = Path::new(path_str);
            if path.is_file() {
                let file_name = path.file_name().unwrap().to_string_lossy();
                let new_name = ascii::to_ascii(&file_name);

                if new_name != *file_name {
                    let new_path = path.parent().unwrap().join(&new_name);
                    operations.push((path.to_path_buf(), new_path));
                }
            }
        }
    }

    if operations.is_empty() {
        return;
    }

    if !opts.silent && !opts.force {
        println!("This is a DRY-RUN");
    }

    for (old, new) in &operations {
        if !opts.silent {
            println!("{} -> {}", old.display(), new.display());
        }
    }

    if opts.force {
        for (old, new) in &operations {
            if opts.backup && !opts.silent {
                let backup_path = format!("{}.bk", old.display());
                println!("Info:  Backup created - {} -> {}", old.display(), backup_path);
                let _ = fs::copy(old, &backup_path);
            }
            if let Err(e) = fs::rename(old, new) {
                eprintln!("Error renaming {} to {}: {}", old.display(), new.display(), e);
                process::exit(1);
            }
        }
    }

    // Handle dump file
    if !opts.no_dump && (opts.dump || opts.force) {
        let dump_ops: Vec<Operation> = operations
            .iter()
            .map(|(src, tgt)| Operation {
                source: src.file_name().unwrap().to_string_lossy().to_string(),
                target: tgt.file_name().unwrap().to_string_lossy().to_string(),
            })
            .collect();

        let dump = DumpFile {
            date: Local::now().format("%Y-%m-%d %H:%M:%S").to_string(),
            operations: dump_ops,
        };

        let filename = format!("{}{}.json", opts.dump_prefix, Local::now().format("%Y-%m-%d_%H%M%S"));
        if let Ok(json) = serde_json::to_string_pretty(&dump) {
            let _ = fs::write(&filename, json);
        }
    }
}
