        for path_str in paths {
            let path = Path::new(path_str);
            for entry in WalkDir::new(path)
                .into_iter()
                .filter_map(|e| e.ok())
                .filter(|e| {
                    if !opts.hidden && e.file_name().to_string_lossy().starts_with('.') {
                        return false;
                    }
                    if let Some(max_depth) = opts.max_depth {
                        let depth = e.path().components().count().saturating_sub(path.components().count());
                        if depth > max_depth {
                            return false;
                        }
                    }
                    if e.path().is_dir() && !opts.include_dirs {
                        return false;
                    }
                    true
                })
            {
                let file_path = entry.path();
                let file_name = file_path.file_name().unwrap().to_string_lossy();
                let new_name = ascii::to_ascii(&file_name);

                if new_name != *file_name {
                    let new_path = file_path.parent().unwrap().join(&new_name);
                    operations.push((file_path.to_path_buf(), new_path));
                }
            }
        }
