fn apply_transform(text: &str, transform: ReplaceTransform) -> String {
    match transform {
        ReplaceTransform::Upper => text.to_uppercase(),
        ReplaceTransform::Lower => text.to_lowercase(),
        ReplaceTransform::Ascii => ascii::to_ascii(text),
    }
}

fn apply_replacements(
    text: &str,
    regex: &Regex,
    replacement: &str,
    limit: Option<usize>,
    transform: Option<ReplaceTransform>,
) -> String {
    let limit = limit.unwrap_or(0);

    if limit == 0 {
        // Replace all
        let result = if let Some(t) = transform {
            regex.replace_all(text, |caps: &regex::Captures| {
                let matched = &caps[0];
                apply_transform(matched, t)
            }).to_string()
        } else {
            regex.replace_all(text, replacement).to_string()
        };
        result
    } else {
        // Replace limited - need to do this manually
        let mut result = text.to_string();
        let mut offset = 0;
        let mut count = 0;

        for m in regex.find_iter(text) {
            if count >= limit {
                break;
            }
            let start = m.start() + offset;
            let end = m.end() + offset;
            let matched = &text[m.start()..m.end()];
            let replacement_text = if let Some(t) = transform {
                apply_transform(matched, t)
            } else {
                replacement.to_string()
            };
            result.replace_range(start..end, &replacement_text);
            offset += replacement_text.len() as i32 - (m.end() - m.start()) as i32;
            count += 1;
        }
        result
    }
