            for entry in entries {
                if entry.is_file() {
                    let file_name = entry.file_name().unwrap().to_string_lossy();

                    if regex.is_match(&file_name) {
                        let new_name = apply_replacements(
                            &file_name,
                            &regex,
                            replacement,
                            replace_limit,
                            replace_transform,
                        );

                        if new_name != *file_name {
                            let new_path = entry.parent().unwrap().join(&*new_name);
