fn get_current_timestamp() -> String {
    use std::time::SystemTime;
    let now = SystemTime::now();
    let elapsed = now.duration_since(SystemTime::UNIX_EPOCH).unwrap();
    let seconds = elapsed.as_secs();
    let nanos = elapsed.subsec_nanos();

    // Simple date formatting
    let total_days = seconds / 86400;
    let years = (total_days / 365) as i32;
    let remaining_days = (total_days % 365) as i32;

    let month = if remaining_days < 31 { 1 }
                else if remaining_days < 59 { 2 }
                else if remaining_days < 90 { 3 }
                else if remaining_days < 120 { 4 }
                else if remaining_days < 151 { 5 }
                else if remaining_days < 181 { 6 }
                else if remaining_days < 212 { 7 }
                else if remaining_days < 243 { 8 }
                else if remaining_days < 273 { 9 }
                else if remaining_days < 304 { 10 }
                else if remaining_days < 334 { 11 }
                else { 12 };

    let year = 1970 + years;
    let day = if remaining_days < 31 { remaining_days + 1 }
              else if remaining_days < 59 { remaining_days - 30 }
              else if remaining_days < 90 { remaining_days - 58 }
              else if remaining_days < 120 { remaining_days - 89 }
              else if remaining_days < 151 { remaining_days - 119 }
              else if remaining_days < 181 { remaining_days - 150 }
              else if remaining_days < 212 { remaining_days - 180 }
              else if remaining_days < 243 { remaining_days - 211 }
              else if remaining_days < 273 { remaining_days - 242 }
              else if remaining_days < 304 { remaining_days - 272 }
              else if remaining_days < 334 { remaining_days - 303 }
              else { remaining_days - 333 };

    let secs_today = seconds % 86400;
    let hours = secs_today / 3600;
    let minutes = (secs_today % 3600) / 60;
    let secs = secs_today % 60;

    format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02}", year, month, day, hours, minutes, secs)
}

