fn should_use_color(mode: ColorMode) -> bool {
    match mode {
        ColorMode::Always => true,
        ColorMode::Never => false,
        ColorMode::Auto => cli::atty::is(cli::atty::Stream::Stdout),
    }
}

fn apply_transform(text: &str, transform: ReplaceTransform) -> String {
    match transform {
        ReplaceTransform::Upper => text.to_uppercase(),
        ReplaceTransform::Lower => text.to_lowercase(),
        ReplaceTransform::Ascii => ascii::to_ascii(text),
    }
}

fn apply_replacements(
    text: &str,
    regex: &Regex,
    replacement: &str,
    limit: Option<usize>,
    transform: Option<ReplaceTransform>,
) -> String {
    let limit = limit.unwrap_or(0);

    if limit == 0 {
        // Replace all
        let result = if let Some(t) = transform {
            regex.replace_all(text, |caps: &regex::Captures| {
                let matched = &caps[0];
                apply_transform(matched, t)
            }).to_string()
        } else {
            regex.replace_all(text, replacement).to_string()
        };
        result
    } else {
        // Replace limited - need to do this manually
        let mut result = text.to_string();
        let mut offset = 0;
        let mut count = 0;

        for m in regex.find_iter(text) {
            if count >= limit {
                break;
            }
            let start = m.start() + offset;
            let end = m.end() + offset;
            let matched = &text[m.start()..m.end()];
            let replacement_text = if let Some(t) = transform {
                apply_transform(matched, t)
            } else {
                replacement.to_string()
            };
            result.replace_range(start..end, &replacement_text);
            offset += replacement_text.len() as i32 - (m.end() - m.start()) as i32;
            count += 1;
        }
        result
    }
}

fn print_colored_rename(old_name: &str, new_name: &str) {
    print!("\x1b[90m{}\x1b[0m -> ", old_name);

    let old_chars: Vec<char> = old_name.chars().collect();
    let new_chars: Vec<char> = new_name.chars().collect();

    let mut in_highlight = false;
    let mut i = 0;

    for nc in &new_chars {
        if i < old_chars.len() {
            let oc = old_chars[i];
            if oc != *nc {
                if !in_highlight {
                    print!("\x1b[1;31m");
                    in_highlight = true;
                }
                print!("{}", nc);
            } else {
                if in_highlight {
                    print!("\x1b[0m\x1b[32m");
                    in_highlight = false;
                }
                print!("{}", nc);
            }
            i += 1;
        } else {
            if !in_highlight {
                print!("\x1b[32m");
                in_highlight = true;
            }
            print!("{}", nc);
        }
    }

    if in_highlight {
        print!("\x1b[0m");
    }

    println!();
}

fn walk_directory(
    path: &Path,
    max_depth: Option<usize>,
    include_hidden: bool,
    base_path: &Path,
) -> Vec<PathBuf> {
    let mut result = Vec::new();

    if let Ok(entries) = fs::read_dir(path) {
        for entry in entries.flatten() {
            let path = entry.path();
            let file_name = path.file_name().unwrap().to_string_lossy();

            // Skip hidden files if needed
            if !include_hidden && file_name.starts_with('.') {
                continue;
            }

            // Check max depth
            if let Some(max) = max_depth {
                let depth = path.components().count().saturating_sub(base_path.components().count());
                if depth > max {
                    continue;
                }
            }

            result.push(path);
        }
    }

    result
}

fn handle_regex(
    expression: &str,
    replacement: &str,
    paths: &[String],
    dry_run: bool,
    force: bool,
    backup: bool,
    silent: bool,
    color: ColorMode,
    dump: bool,
    dump_prefix: &str,
    no_dump: bool,
    replace_limit: Option<usize>,
    replace_transform: Option<ReplaceTransform>,
    include_dirs: bool,
    recursive: bool,
    max_depth: Option<usize>,
    hidden: bool,
) {
    if hidden && !recursive {
        eprintln!("error: the following required arguments were not provided:\n  --recursive");
        eprintln!();
        eprintln!("Usage: executable regex --recursive --hidden <EXPRESSION> <REPLACEMENT> <PATH(S)>...");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        process::exit(2);
    }

    let regex = match Regex::new(expression) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("Error: Invalid regex: {}", e);
            process::exit(1);
        }
    };

    let use_color = should_use_color(color);
    let mut operations = Vec::new();

    for path_str in paths {
        let path = Path::new(path_str);

        if path.is_file() {
            let file_name = path.file_name().unwrap().to_string_lossy();

            if regex.is_match(&file_name) {
                let new_name = apply_replacements(
                    &file_name,
                    &regex,
                    replacement,
                    replace_limit,
                    replace_transform,
                );

                if new_name != *file_name {
                    let new_path = path.parent().unwrap().join(&*new_name);
                    operations.push((path.to_path_buf(), new_path));
                }
            }
        } else if path.is_dir() && recursive {
            let entries = walk_directory(&path, max_depth, hidden, &path);
            for entry in entries {
                if entry.is_file() {
                    let file_name = entry.file_name().unwrap().to_string_lossy();

                    if regex.is_match(&file_name) {
                        let new_name = apply_replacements(
                            &file_name,
                            &regex,
                            replacement,
                            replace_limit,
                            replace_transform,
                        );

                        if new_name != *file_name {
                            let new_path = entry.parent().unwrap().join(&*new_name);
                            operations.push((entry.to_path_buf(), new_path));
                        }
                    }
                } else if entry.is_dir() && include_dirs {
                    let file_name = entry.file_name().unwrap().to_string_lossy();

                    if regex.is_match(&file_name) {
                        let new_name = apply_replacements(
                            &file_name,
                            &regex,
                            replacement,
                            replace_limit,
                            replace_transform,
                        );

                        if new_name != *file_name {
                            let new_path = entry.parent().unwrap().join(&*new_name);
                            operations.push((entry.to_path_buf(), new_path));
                        }
                    }
                }
            }
        }
    }

    if operations.is_empty() {
        return;
    }

    // Check for duplicate names
    let mut name_map: HashMap<String, Vec<String>> = HashMap::new();
    for (old, new) in &operations {
        let new_name = new.to_string_lossy().to_string();
        name_map.entry(new_name).or_insert_with(Vec::new).push(old.to_string_lossy().to_string());
    }

    for (new_name, old_names) in name_map.iter() {
        if old_names.len() > 1 {
            if !silent {
                eprintln!("Error: Files will have the same name");
                eprintln!();
                for old in old_names {
                    eprintln!("{}->", old);
                }
                eprintln!("{}", new_name);
                eprintln!();
                for old in old_names {
                    eprintln!("{}->", old);
                }
                eprintln!("{}", new_name);
                eprintln!();
            }
            process::exit(1);
        }
    }

    if !silent && !force {
        if use_color {
            println!("\x1b[1mThis is a DRY-RUN\x1b[0m");
        } else {
            println!("This is a DRY-RUN");
        }
    }

    for (old, new) in &operations {
        if !silent {
            if use_color {
                let old_name = old.file_name().unwrap().to_string_lossy();
                let new_name = new.file_name().unwrap().to_string_lossy();
                print_colored_rename(&old_name, &new_name);
            } else {
                println!("{} -> {}", old.display(), new.display());
            }
        }
    }

    if force {
        for (old, new) in &operations {
            if backup && !silent {
                let backup_path = format!("{}.bk", old.display());
                println!("Info:  Backup created - {} -> {}", old.display(), backup_path);
                let _ = fs::copy(old, &backup_path);
            }
            if let Err(e) = fs::rename(old, new) {
                eprintln!("Error renaming {} to {}: {}", old.display(), new.display(), e);
                process::exit(1);
            }
        }
    }

    // Handle dump file
    if !no_dump && (dump || force) {
        let dump_ops: Vec<Operation> = operations
            .iter()
            .map(|(src, tgt)| Operation {
                source: src.file_name().unwrap().to_string_lossy().to_string(),
                target: tgt.file_name().unwrap().to_string_lossy().to_string(),
            })
            .collect();

        let dump_file = DumpFile {
            date: get_current_timestamp(),
            operations: dump_ops,
        };

        let filename = format!("{}{}.json", dump_prefix, get_timestamp_for_filename());
        if let Ok(json) = serde_json::to_string_pretty(&dump_file) {
            let _ = fs::write(&filename, json);
        }
    }
}

fn handle_from_file(
    dumpfile: &str,
    dry_run: bool,
    force: bool,
    backup: bool,
    silent: bool,
    color: ColorMode,
    dump: bool,
    dump_prefix: &str,
    no_dump: bool,
    undo: bool,
) {
    let use_color = should_use_color(color);

    match fs::read_to_string(dumpfile) {
        Ok(content) => {
            match serde_json::from_str::<DumpFile>(&content) {
                Ok(mut dump_data) => {
                    if undo {
                        // Reverse the operations
                        for op in &mut dump_data.operations {
                            std::mem::swap(&mut op.source, &mut op.target);
                        }
                    }

                    if !silent && !force {
                        if use_color {
                            println!("\x1b[1mThis is a DRY-RUN\x1b[0m");
                        } else {
                            println!("This is a DRY-RUN");
                        }
                    }

                    for op in &dump_data.operations {
                        if !silent {
                            println!("{} -> {}", op.source, op.target);
                        }
                    }

                    if force {
                        for op in &dump_data.operations {
                            let src = Path::new(&op.source);
                            let dst = Path::new(&op.target);

                            if backup && !silent {
                                let backup_path = format!("{}.bk", src.display());
                                println!("Info:  Backup created - {} -> {}", src.display(), backup_path);
                                let _ = fs::copy(src, &backup_path);
                            }

                            if let Err(e) = fs::rename(src, dst) {
                                eprintln!("Error renaming {} to {}: {}", src.display(), dst.display(), e);
                                process::exit(1);
                            }
                        }
                    }

                    // Handle dump file
                    if !no_dump && (dump || force) {
                        let new_dump = DumpFile {
                            date: get_current_timestamp(),
                            operations: dump_data.operations.clone(),
                        };

                        let filename = format!("{}{}.json", dump_prefix, get_timestamp_for_filename());
                        if let Ok(json) = serde_json::to_string_pretty(&new_dump) {
                            let _ = fs::write(&filename, json);
                        }
                    }
                }
                Err(e) => {
                    eprintln!("Error parsing dump file: {}", e);
                    process::exit(1);
                }
            }
        }
        Err(e) => {
            eprintln!("Error reading dump file: {}", e);
            process::exit(1);
        }
    }
}

fn handle_to_ascii(
    paths: &[String],
    dry_run: bool,
    force: bool,
    backup: bool,
    silent: bool,
    color: ColorMode,
    dump: bool,
    dump_prefix: &str,
    no_dump: bool,
    include_dirs: bool,
    recursive: bool,
    max_depth: Option<usize>,
    hidden: bool,
) {
    let use_color = should_use_color(color);
    let mut operations = Vec::new();

    for path_str in paths {
        let path = Path::new(path_str);

        if path.is_file() {
            let file_name = path.file_name().unwrap().to_string_lossy();
            let new_name = ascii::to_ascii(&file_name);

            if new_name != *file_name {
                let new_path = path.parent().unwrap().join(&new_name);
                operations.push((path.to_path_buf(), new_path));
            }
        } else if path.is_dir() && recursive {
            let entries = walk_directory(&path, max_depth, hidden, &path);
            for entry in entries {
                if entry.is_file() {
                    let file_name = entry.file_name().unwrap().to_string_lossy();
                    let new_name = ascii::to_ascii(&file_name);

                    if new_name != *file_name {
                        let new_path = entry.parent().unwrap().join(&new_name);
                        operations.push((entry.to_path_buf(), new_path));
                    }
                } else if entry.is_dir() && include_dirs {
                    let file_name = entry.file_name().unwrap().to_string_lossy();
                    let new_name = ascii::to_ascii(&file_name);

                    if new_name != *file_name {
                        let new_path = entry.parent().unwrap().join(&new_name);
                        operations.push((entry.to_path_buf(), new_path));
                    }
                }
            }
        }
    }

    if operations.is_empty() {
        return;
    }

    if !silent && !force {
        if use_color {
            println!("\x1b[1mThis is a DRY-RUN\x1b[0m");
        } else {
            println!("This is a DRY-RUN");
        }
    }

    for (old, new) in &operations {
        if !silent {
            println!("{} -> {}", old.display(), new.display());
        }
    }

    if force {
        for (old, new) in &operations {
            if backup && !silent {
                let backup_path = format!("{}.bk", old.display());
                println!("Info:  Backup created - {} -> {}", old.display(), backup_path);
                let _ = fs::copy(old, &backup_path);
            }
            if let Err(e) = fs::rename(old, new) {
                eprintln!("Error renaming {} to {}: {}", old.display(), new.display(), e);
                process::exit(1);
            }
        }
    }

    // Handle dump file
    if !no_dump && (dump || force) {
        let dump_ops: Vec<Operation> = operations
            .iter()
            .map(|(src, tgt)| Operation {
                source: src.file_name().unwrap().to_string_lossy().to_string(),
                target: tgt.file_name().unwrap().to_string_lossy().to_string(),
            })
            .collect();

        let dump_file = DumpFile {
            date: get_current_timestamp(),
            operations: dump_ops,
        };

        let filename = format!("{}{}.json", dump_prefix, get_timestamp_for_filename());
        if let Ok(json) = serde_json::to_string_pretty(&dump_file) {
            let _ = fs::write(&filename, json);
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() > 1 && args[1] == "--version" {
        println!("rnr 0.5.1");
        return;
    }

    if args.len() == 1 || (args.len() > 1 && (args[1] == "--help" || args[1] == "-h")) {
        println!("RnR is a command-line tool to rename multiple files and directories that");
        println!("supports regular expressions");
        println!();
        println!("Usage: executable <COMMAND>");
        println!();
        println!("Commands:");
        println!("  regex      Rename files and directories using a regular expression");
        println!("  from-file  Read operations from a dump file");
        println!("  to-ascii   Replace file name UTF-8 chars with ASCII chars representation");
        println!("  help       Print this message or the help of the given subcommand(s)");
        println!();
        println!("Options:");
        println!("  -h, --help     Print help");
        println!("  -V, --version  Print version");
        return;
    }

    // Simple argument parsing
    if args.len() > 1 && args[1] == "regex" {
        if args.len() < 4 {
            eprintln!("error: the following required arguments were not provided:\n  <EXPRESSION>\n  <REPLACEMENT>\n  <PATH(S)>...");
            process::exit(2);
        }

        let expression = &args[2];
        let replacement = &args[3];
        let mut paths = Vec::new();
        let mut dry_run = true;
        let mut force = false;
        let mut backup = false;
        let mut silent = false;
        let mut color = ColorMode::Auto;
        let mut dump = false;
        let mut dump_prefix = "rnr-".to_string();
        let mut no_dump = false;
        let mut replace_limit: Option<usize> = None;
        let mut replace_transform: Option<ReplaceTransform> = None;
        let mut include_dirs = false;
        let mut recursive = false;
        let mut max_depth: Option<usize> = None;
        let mut hidden = false;

        let mut i = 4;
        while i < args.len() {
            match args[i].as_str() {
                "-n" | "--dry-run" => dry_run = true,
                "-f" | "--force" => {
                    force = true;
                    dry_run = false;
                }
                "-b" | "--backup" => backup = true,
                "-s" | "--silent" => silent = true,
                "--color" => {
                    i += 1;
                    if i < args.len() {
                        color = match args[i].as_str() {
                            "always" => ColorMode::Always,
                            "never" => ColorMode::Never,
                            "auto" => ColorMode::Auto,
                            _ => ColorMode::Auto,
                        };
                    }
                }
                "--dump" => dump = true,
                "--dump-prefix" => {
                    i += 1;
                    if i < args.len() {
                        dump_prefix = args[i].clone();
                    }
                }
                "--no-dump" => no_dump = true,
                "-l" | "--replace-limit" => {
                    i += 1;
                    if i < args.len() {
                        replace_limit = args[i].parse().ok();
                    }
                }
                "-t" | "--replace-transform" => {
                    i += 1;
                    if i < args.len() {
