            '+' => {
                // One or more
                if !self.char_matches(&pattern[pattern_pos], *text_pos, text) {
                    return None;
                }
                *text_pos += 1;

                while self.char_matches(&pattern[pattern_pos], *text_pos, text) {
                    *text_pos += 1;
                }
                Some(new_pattern_pos)
            }
            '?' => {
                // Zero or one
                if self.char_matches(&pattern[pattern_pos], *text_pos, text) {
                    *text_pos += 1;
                }
                Some(new_pattern_pos)
            }
            _ => None,
        }
    }

    fn char_matches(&self, pattern_char: &char, text_pos: usize, text: &[char]) -> bool {
        if text_pos >= text.len() {
            return false;
        }

        match pattern_char {
            '.' => true,
            '\\' => false, // Handled separately
            c => text[text_pos] == *c,
        }
    }

    pub fn find_iter<'t>(&self, text: &'t str) -> FindIter<'t> {
        FindIter {
            regex: self,
            text,
            pos: 0,
        }
    }

    pub fn replace_all<F>(&self, text: &str, mut replacer: F) -> String
    where
        F: FnMut(&Captures) -> String,
    {
        let mut result = String::new();
        let mut last_end = 0;

        for m in self.find_iter(text) {
            result.push_str(&text[last_end..m.start]);
            let cap = Captures {
                regex: self,
                text,
                m: m.clone(),
            };
            result.push_str(&replacer(&cap));
            last_end = m.end;
        }

        result.push_str(&text[last_end..]);
        result
    }
}

#[derive(Clone)]
pub struct Match {
    pub start: usize,
    pub end: usize,
}

pub struct Captures<'t> {
    regex: &'t Regex,
    text: &'t str,
    m: Match,
}

impl<'t> Captures<'t> {
    pub fn get(&self, i: usize) -> Option<&'t str> {
        if i == 0 {
            Some(&self.text[self.m.start..self.m.end])
        } else {
            None
        }
    }
}

impl<'t> std::ops::Index<usize> for Captures<'t> {
    type Output = str;

    fn index(&self, i: usize) -> &str {
        self.get(i).unwrap_or("")
    }
}

pub struct FindIter<'t> {
    regex: &'t Regex,
    text: &'t str,
    pos: usize,
}

impl<'t> Iterator for FindIter<'t> {
    type Item = Match;

    fn next(&mut self) -> Option<Self::Item> {
        for i in self.pos..=self.text.len() {
            if let Some(m) = self.regex.match_at(self.text, i) {
                self.pos = m.end.max(m.start + 1);
                return Some(m);
            }
        }
        None
    }
}
