fn get_current_timestamp() -> String {
    use std::time::SystemTime;
    let now = SystemTime::now();
    let elapsed = now.duration_since(SystemTime::UNIX_EPOCH).unwrap();
    let seconds = elapsed.as_secs();

    // Simple date formatting - convert Unix timestamp to date
    let days_since_epoch = seconds / 86400;
    let year = 1970 + (days_since_epoch / 365) as i32;
    let day_of_year = (days_since_epoch % 365) as i32;

    let month = if day_of_year < 31 { 1 }
                else if day_of_year < 59 { 2 }
                else if day_of_year < 90 { 3 }
                else if day_of_year < 120 { 4 }
                else if day_of_year < 151 { 5 }
                else if day_of_year < 181 { 6 }
                else if day_of_year < 212 { 7 }
                else if day_of_year < 243 { 8 }
                else if day_of_year < 273 { 9 }
                else if day_of_year < 304 { 10 }
                else if day_of_year < 334 { 11 }
                else { 12 };

    let month_days = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    let mut day = day_of_year;
    for m in 1..month {
        day -= month_days[m as usize];
    }
    day += 1;

    let secs_today = seconds % 86400;
    let hours = secs_today / 3600;
    let minutes = (secs_today % 3600) / 60;
    let secs = secs_today % 60;

    format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02}", year, month, day, hours, minutes, secs)
}

