                    let new_name = regex.replace(&file_name, replacement, replace_limit, replace_transform);
                    if new_name != *file_name {
                        let new_path = entry_path.parent().unwrap().join(&new_name);
                        operations.push((entry_path, new_path));
                    }
                }
            } else if entry_path.is_dir() {
                if include_dirs && regex.is_match(&file_name) {
