fn collect_files_recursive(
    path: &Path,
    regex: &regex_simple::Regex,
    replacement: &str,
    replace_limit: Option<usize>,
    replace_transform: Option<ReplaceTransform>,
    max_depth: Option<usize>,
    hidden: bool,
    include_dirs: bool,
    current_depth: usize,
    operations: &mut Vec<(PathBuf, PathBuf)>,
) {
    if let Some(max) = max_depth {
        if current_depth > max {
            return;
        }
    }

    if let Ok(entries) = fs::read_dir(path) {
        for entry in entries.flatten() {
            let entry_path = entry.path();
            let file_name = entry_path.file_name().unwrap().to_string_lossy();

            if !hidden && file_name.starts_with('.') {
                continue;
            }

            if entry_path.is_file() {
                if regex.is_match(&file_name) {
                    let new_name = regex.replace(&file_name, replacement, replace_limit, replace_transform);
                    if new_name != *file_name {
                        let new_path = entry_path.parent().unwrap().join(&new_name);
                        operations.push((entry_path, new_path));
                    }
                }
            } else if entry_path.is_dir() {
                if include_dirs && regex.is_match(&file_name) {
                    let new_name = regex.replace(&file_name, replacement, replace_limit, replace_transform);
                    if new_name != *file_name {
                        let new_path = entry_path.parent().unwrap().join(&new_name);
                        operations.push((entry_path.clone(), new_path));
                    }
                }

                collect_files_recursive(
                    &entry_path,
                    regex,
                    replacement,
                    replace_limit,
                    replace_transform,
                    max_depth,
                    hidden,
                    include_dirs,
                    current_depth + 1,
                    operations,
                );
            }
        }
    }
