    let secs_today = seconds % 86400;
    let hours = secs_today / 3600;
    let minutes = (secs_today % 3600) / 60;
    let secs = secs_today % 60;

    format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02}", year, month, day, hours, minutes, secs)
}

