fn apply_transform(text: &str, transform: ReplaceTransform) -> String {
    match transform {
        ReplaceTransform::Upper => text.to_uppercase(),
        ReplaceTransform::Lower => text.to_lowercase(),
        ReplaceTransform::Ascii => ascii::to_ascii(text),
    }
}

fn serialize_json(ops: &[(String, String)]) -> String {
    let mut json = format!("{{\n  \"date\": \"{}\",\n  \"operations\": [\n", get_current_timestamp());

    for (i, (src, tgt)) in ops.iter().enumerate() {
        json.push_str(&format!("    {{\n      \"source\": \"{}\",\n      \"target\": \"{}\"\n    }}", src, tgt));
        if i < ops.len() - 1 {
            json.push(',');
        }
        json.push('\n');
    }

    json.push_str("  ]\n}\n");
    json
}

fn deserialize_json(content: &str) -> Option<Vec<(String, String)>> {
    // Simple JSON parsing for our specific format
    let mut ops = Vec::new();

    // Find all operation blocks
    let mut in_ops = false;
    let mut current_src = String::new();
    let mut current_tgt = String::new();
    let mut reading_source = false;
    let mut reading_target = false;

    for line in content.lines() {
        let trimmed = line.trim();

        if trimmed.contains("\"operations\"") {
            in_ops = true;
        } else if trimmed == "{" && in_ops {
            current_src.clear();
            current_tgt.clear();
            reading_source = false;
            reading_target = false;
        } else if trimmed.starts_with("\"source\"") {
            if let Some(start) = trimmed.find('"') {
                if let Some(end) = trimmed.rfind('"') {
                    if start < end {
                        current_src = trimmed[start + 1..end].to_string();
                        reading_source = true;
                    }
                }
            }
        } else if trimmed.starts_with("\"target\"") {
            if let Some(start) = trimmed.find('"') {
                if let Some(end) = trimmed.rfind('"') {
                    if start < end {
                        current_tgt = trimmed[start + 1..end].to_string();
                        reading_target = true;
                    }
                }
            }
        } else if trimmed == "}" && reading_source && reading_target {
            ops.push((current_src.clone(), current_tgt.clone()));
        }
    }

    if ops.is_empty() {
        None
    } else {
        Some(ops)
    }
}

