use crate::cli::ReplaceTransform;
use crate::apply_transform;
use std::collections::HashMap;

pub struct Regex {
    pattern: String,
}

impl Regex {
    pub fn new(pattern: &str) -> Result<Self, String> {
        Ok(Regex {
            pattern: pattern.to_string(),
        })
    }

    pub fn is_match(&self, text: &str) -> bool {
        self.find_matches(text).len() > 0
    }

    pub fn replace(&self, text: &str, replacement: &str, limit: Option<usize>, transform: Option<ReplaceTransform>) -> String {
        let matches = self.find_matches(text);
        if matches.is_empty() {
            return text.to_string();
        }

        let mut result = String::new();
        let mut last_end = 0;
        let limit = limit.unwrap_or(0);
        let mut count = 0;

        for (start, end) in matches {
            if limit > 0 && count >= limit {
                break;
            }

            result.push_str(&text[last_end..start]);

            let matched = &text[start..end];
            let replacement_str = if let Some(t) = transform {
                apply_transform(matched, t)
            } else {
                self.process_replacement(replacement, matched, text, start, end)
            };

            result.push_str(&replacement_str);
            last_end = end;
            count += 1;
        }

        result.push_str(&text[last_end..]);
        result
    }

    fn process_replacement(&self, replacement: &str, matched: &str, text: &str, start: usize, end: usize) -> String {
        let mut result = replacement.to_string();

        // Replace $0 with the full match
        result = result.replace("$0", matched);

        // Extract capture groups if any
        if self.pattern.contains('(') {
            let captures = self.extract_captures(&matched);
            for (i, cap) in captures.iter().enumerate() {
                result = result.replace(&format!("${}", i + 1), cap);
            }
        }

        result
    }

    fn find_matches(&self, text: &str) -> Vec<(usize, usize)> {
        let mut matches = Vec::new();
        let pattern_chars: Vec<char> = self.pattern.chars().collect();
        let text_bytes = text.as_bytes();

        'outer: for start_pos in 0..=text.len() {
            if let Some((end_pos, _)) = self.try_match(&pattern_chars, text, start_pos) {
                matches.push((start_pos, end_pos));
                // Continue searching after this match
            }
        }

        matches
    }

    fn try_match(&self, pattern: &[char], text: &str, text_pos: usize) -> Option<(usize, HashMap<usize, String>)> {
        let mut captures = HashMap::new();
        match self.match_pattern(pattern, 0, text, text_pos) {
            Some(end_pos) => Some((end_pos, captures)),
            None => None,
        }
    }

    fn match_pattern(&self, pattern: &[char], pat_pos: usize, text: &str, text_pos: usize) -> Option<usize> {
        if pat_pos >= pattern.len() {
            return Some(text_pos);
        }

        let text_chars: Vec<char> = text.chars().collect();
        let mut p = pat_pos;
        let mut t = text_pos;

        while p < pattern.len() {
            match pattern[p] {
                '(' => {
                    // Find matching )
                    let mut depth = 1;
                    let mut group_end = p + 1;
                    while group_end < pattern.len() && depth > 0 {
                        if pattern[group_end] == '(' {
                            depth += 1;
                        } else if pattern[group_end] == ')' {
                            depth -= 1;
                        }
                        group_end += 1;
                    }

                    // Try to match the group content
                    let group_pat = &pattern[p+1..group_end-1];

                    // Check if the next char is a quantifier
                    if group_end < pattern.len() && matches!(pattern[group_end], '*' | '+' | '?') {
                        // Handle quantified group
                        let quantifier = pattern[group_end];
                        match quantifier {
                            '*' => {
                                // Zero or more
                                loop {
                                    if let Some(new_t) = self.match_pattern(group_pat, 0, text, t) {
                                        t = new_t;
                                    } else {
                                        break;
                                    }
                                }
                                p = group_end + 1;
                            }
                            '+' => {
                                // One or more
                                if let Some(new_t) = self.match_pattern(group_pat, 0, text, t) {
                                    t = new_t;
                                    loop {
                                        if let Some(new_t2) = self.match_pattern(group_pat, 0, text, t) {
                                            t = new_t2;
                                        } else {
                                            break;
                                        }
                                    }
                                    p = group_end + 1;
                                } else {
                                    return None;
                                }
                            }
                            '?' => {
                                // Zero or one
                                if let Some(new_t) = self.match_pattern(group_pat, 0, text, t) {
                                    t = new_t;
                                }
                                p = group_end + 1;
                            }
                            _ => {
                                p = group_end + 1;
                            }
                        }
                    } else {
                        if let Some(new_t) = self.match_pattern(group_pat, 0, text, t) {
                            t = new_t;
                            p = group_end;
                        } else {
                            return None;
                        }
                    }
                }
                '\\' if p + 1 < pattern.len() => {
                    p += 1;
                    match pattern[p] {
                        'd' => {
                            if t < text_chars.len() && text_chars[t].is_ascii_digit() {
                                t += 1;
                                p += 1;
                            } else {
                                return None;
                            }
                        }
                        'w' => {
                            if t < text_chars.len() && (text_chars[t].is_alphanumeric() || text_chars[t] == '_') {
                                t += 1;
                                p += 1;
                            } else {
                                return None;
                            }
                        }
                        's' => {
                            if t < text_chars.len() && text_chars[t].is_whitespace() {
                                t += 1;
                                p += 1;
                            } else {
                                return None;
                            }
                        }
                        c => {
                            if t < text_chars.len() && text_chars[t] == c {
                                t += 1;
                                p += 1;
                            } else {
                                return None;
                            }
                        }
                    }
                }
                '.' => {
                    if t < text_chars.len() {
                        // Check for quantifier
                        if p + 1 < pattern.len() && matches!(pattern[p + 1], '*' | '+' | '?') {
                            match pattern[p + 1] {
                                '*' => {
                                    t = text_chars.len();
                                    p += 2;
                                }
                                '+' => {
                                    if t < text_chars.len() {
                                        t = text_chars.len();
                                        p += 2;
                                    } else {
                                        return None;
                                    }
                                }
                                '?' => {
                                    t += 1;
                                    p += 2;
                                }
                                _ => {
                                    t += 1;
                                    p += 1;
                                }
                            }
                        } else {
                            t += 1;
                            p += 1;
                        }
                    } else {
                        return None;
                    }
                }
                c => {
                    // Check for quantifier
                    if p + 1 < pattern.len() && matches!(pattern[p + 1], '*' | '+' | '?') {
                        let quantifier = pattern[p + 1];
                        match quantifier {
                            '*' => {
                                while t < text_chars.len() && text_chars[t] == c {
                                    t += 1;
                                }
                                p += 2;
                            }
                            '+' => {
                                if t < text_chars.len() && text_chars[t] == c {
                                    t += 1;
                                    while t < text_chars.len() && text_chars[t] == c {
                                        t += 1;
                                    }
                                    p += 2;
                                } else {
                                    return None;
                                }
                            }
                            '?' => {
                                if t < text_chars.len() && text_chars[t] == c {
                                    t += 1;
                                }
                                p += 2;
                            }
                            _ => {
                                if t < text_chars.len() && text_chars[t] == c {
                                    t += 1;
                                    p += 1;
                                } else {
                                    return None;
                                }
                            }
                        }
                    } else {
                        if t < text_chars.len() && text_chars[t] == c {
                            t += 1;
                            p += 1;
                        } else {
                            return None;
                        }
                    }
                }
            }
        }

        Some(t)
    }

    fn extract_captures(&self, matched: &str) -> Vec<String> {
        // For now, just return the matched text as a single capture
        vec![matched.to_string()]
    }
}
